const MIN_MES = 30 * 24 * 60; // un mes de 30 días = 43.200 minutos
const fmt = (m) => m >= 60 ? Math.floor(m / 60) + " h " + Math.round(m % 60) + " min" : m.toFixed(1) + " min";
console.log("Disponibilidad | caída permitida por mes de 30 días");
for (const a of [99, 99.5, 99.9, 99.95, 99.99, 99.999]) {
  console.log(String(a).padEnd(8) + "% | " + fmt(MIN_MES * (1 - a / 100)));
}
// En serie: tiene que andar todo. En paralelo: alcanza con que ande uno.
const serie = (...p) => p.reduce((x, y) => x * y, 1);
const paralelo = (...p) => 1 - p.reduce((x, y) => x * (1 - y), 1);
const pct = (x) => (x * 100).toFixed(4) + "%";
const balanceador = 0.9999, web = 0.995, base = 0.999;
console.log("\nUna sola zona (balanceador × web × base):", pct(serie(balanceador, web, base)));
console.log("Web duplicada en dos zonas, fallas independientes:", pct(serie(balanceador, paralelo(web, web), base)));
console.log("Base también duplicada:", pct(serie(balanceador, paralelo(web, web), paralelo(base, base))));
const regional = 0.9995; // algo compartido por todas las zonas, por ejemplo un servicio regional
console.log("Con un componente regional de 99,95% en serie:", pct(serie(regional, balanceador, paralelo(web, web), paralelo(base, base))));
